
import { defineComponent, markRaw } from 'vue';
import { Graphics } from 'pixi.js';

import { inversifyContainer } from '../../inversify/container';
import { loggingModel } from '../../models/logging';
import { environment } from '../../services/environment';
import { eventEmitter } from '../../services/event-emitter';
import { IBaseDebugOption, IDebugSettingType, IDebugTriggerSetting } from '../../types';

import { default as DebugSetting } from './setting-view.vue';
import { SpineIdleHighlighter } from './spine-higlighter';

// Simulates a mid-session WebGL context loss so the static-texture restore path can be tested on
// device (e.g. mobile) without a dev console. Restores shortly after so Pixi can recover.
function simulateWebGLContextLoss(): void {
    const canvas = document.querySelector('canvas');
    const gl = canvas?.getContext('webgl2') || canvas?.getContext('webgl');
    const loseContext = gl?.getExtension('WEBGL_lose_context');

    if (!loseContext) return;

    loseContext.loseContext();
    window.setTimeout(() => loseContext.restoreContext(), 800);
}

const clearGpuContextSetting: IDebugTriggerSetting = {
    name: 'Clear GPU Context',
    onChange: () => simulateWebGLContextLoss(),
    type: 'trigger'
};

export default defineComponent({
    name: 'DebugOverlay',
    components: {
        DebugSetting
    },
    data() {
        return {
            currentError: 'No errors',
            expandString: 'V',
            errorCount: '0/0',
            showDebugOverlay: false,
            heapLimit: '',
            totalHeapSize: '',
            usedHeapSize: '',
            showFPS: environment === 'debug' || environment === 'dev',
            frameRate: '',
            times: [] as number[],
            showAdvanced: false,
            hasSettings: false,
            selectedOption: { name: 'null' },
            errorNumber: 0,
            debugEngineVersion: '',
            fpsWarningLevel: 'normal' as 'normal' | 'warning' | 'critical',
            fpsWarningTimeout: null as number | null,
            fpsPositionRight: true,
            showingSpineHighlighter: false,
            debugLayer: null as Graphics | null,
            spineIdleHighlighter: null as SpineIdleHighlighter | null,
            globalFrame: 0,
            quickOptionsCollapsed: false,
            settingsCollapsed: false
        };
    },
    computed: {
        debugOptions(): IBaseDebugOption[] {
            return inversifyContainer.debugModel.debugTicketOptions;
        },
        debugSettings(): IDebugSettingType[] {
            return [...inversifyContainer.debugModel.debugSettingOptions, clearGpuContextSetting];
        },
        fpsCounterClass(): string {
            const position = this.fpsPositionRight ? 'right' : 'left';
            return `fps-counter fps-${this.fpsWarningLevel} fps-${position}`;
        }
    },
    mounted(): void {
        eventEmitter.on('POPUP_TOGGLE_DEBUG_OVERLAY', (visible: boolean | void) => {
            this.showDebugOverlay = visible ?? !this.showDebugOverlay;
        });

        this.hasSettings = this.debugSettings.length > 0;

        if (this.debugOptions.length > 0) {
            this.selectedOption = this.debugOptions[0];
        }

        eventEmitter.on('POPUP_TOGGLE_DEBUG_OVERLAY', this.onVisibilityChange, this);

        // Start FPS counter if showFPS is true by default
        if (this.showFPS) {
            this.times = [];
            this.runFPS();
        }
    },
    methods: {
        onVisibilityChange(visible: boolean | void): void {
            if (visible) {
                if (Reflect.has(window.performance, 'memory')) {
                    // TODO: look into alternatives as performance.memory is non-standard
                    // https://developer.mozilla.org/en-US/docs/Web/API/Performance/memory
                    interface PerformanceEx extends Performance {
                        memory: {
                            jsHeapSizeLimit: number;
                            totalJSHeapSize: number;
                            usedJSHeapSize: number;
                        };
                    }
                    this.heapLimit = '' + ((window.performance as PerformanceEx).memory.jsHeapSizeLimit / 1024 / 1024).toFixed(2) + 'mb';
                    this.totalHeapSize = '' + ((window.performance as PerformanceEx).memory.totalJSHeapSize / 1024 / 1024).toFixed(2) + 'mb';
                    this.usedHeapSize = '' + ((window.performance as PerformanceEx).memory.usedJSHeapSize / 1024 / 1024).toFixed(2) + 'mb';
                } else {
                    this.heapLimit = 'Memory stats unavailable';
                    this.totalHeapSize = '';
                    this.usedHeapSize = '';
                }

                this.errorNumber = loggingModel.getErrors().length - 1;
                if (loggingModel.getErrors().length > 0) {
                    this.currentError = loggingModel.getErrors()[this.errorNumber];
                } else {
                    this.currentError = 'No error';
                }

                this.errorCount = (this.errorNumber + 1) + '/' + loggingModel.getErrors().length;
            }
        },
        toggleFPS(): void {
            this.showFPS = !this.showFPS;
            if (this.showFPS) {
                this.times = [];
                this.runFPS();
            }
        },
        clearErrors(): void {
            loggingModel.clearErrors();
            this.errorNumber = -1;
            this.currentError = 'No errors';
            this.errorCount = (this.errorNumber + 1) + '/' + loggingModel.getErrors().length;
        },
        nextError(): void {
            if (loggingModel.getErrors().length > 0) {
                if (this.errorNumber < loggingModel.getErrors().length - 1) {
                    this.errorNumber = this.errorNumber + 1;
                }
                this.currentError = loggingModel.getErrors()[this.errorNumber];
            } else {
                this.currentError = 'No errors';
            }
            this.errorCount = (this.errorNumber + 1) + '/' + loggingModel.getErrors().length;
        },
        prevError(): void {
            if (loggingModel.getErrors().length > 0) {
                if (this.errorNumber > 0) {
                    this.errorNumber--;
                }
                this.currentError = loggingModel.getErrors()[this.errorNumber];
            } else {
                this.currentError = 'No errors';
            }
            this.errorCount = (this.errorNumber + 1) + '/' + loggingModel.getErrors().length;
        },
        runFPS(): void {
            window.requestAnimationFrame(() => {
                const now = performance.now();
                while (this.times.length > 0 && this.times[0] <= now - 1000) {
                    this.times.shift();
                }

                this.times.push(now);
                const fps = this.times.length;
                this.frameRate = fps.toString();

                // Check FPS and set warning level
                if (fps < 30) {
                    this.fpsWarningLevel = 'critical';
                    this.clearFpsWarningTimeout();
                } else if (fps < 40) {
                    this.fpsWarningLevel = 'warning';
                    this.clearFpsWarningTimeout();
                } else if (this.fpsWarningLevel !== 'normal') {
                    // FPS is back to normal, schedule return to normal state after 2 seconds
                    if (this.fpsWarningTimeout === null) {
                        this.fpsWarningTimeout = window.setTimeout(() => {
                            this.fpsWarningLevel = 'normal';
                            this.fpsWarningTimeout = null;
                        }, 2000);
                    }
                }

                if (this.showFPS) {
                    this.runFPS();
                }
            });
        },
        clearFpsWarningTimeout(): void {
            if (this.fpsWarningTimeout !== null) {
                window.clearTimeout(this.fpsWarningTimeout);
                this.fpsWarningTimeout = null;
            }
        },
        updateDebugOption(option: IBaseDebugOption): void {
            this.selectedOption = option;
            inversifyContainer.debugModel.updateDebugOption(option);
        },
        closeClick(): void {
            this.showDebugOverlay = false;
        },
        expandClick(): void {
            this.showAdvanced = !this.showAdvanced;
            this.expandString = (this.showAdvanced ? 'Λ' : 'V');
        },
        inspectorClick(): void {
            eventEmitter.emit('DEBUG_INSPECTOR_SHOW_REQUESTED', true);
            this.showDebugOverlay = false;
        },
        setEngineNumber(): void {
            eventEmitter.emit('DEBUG_ENGINE_VERSION_SET', this.debugEngineVersion);
        },
        toggleFpsPosition(): void {
            this.fpsPositionRight = !this.fpsPositionRight;
        },
        updateSpineHighlighter(): void {
            if (this.showingSpineHighlighter && this.spineIdleHighlighter && this.debugLayer) {
                this.globalFrame++;
                this.debugLayer.clear();
                this.spineIdleHighlighter.highlightIdleSpines(
                    window.$pixi.stage,
                    this.debugLayer as Graphics,
                    this.globalFrame
                );
            }
        },
        toggleSpineHighlighter(): void {
            if (!window.$pixi || !window.$pixi.stage) {
                this.showingSpineHighlighter = false;
                return;
            }
            this.showingSpineHighlighter = !this.showingSpineHighlighter;

            if (this.showingSpineHighlighter) {
                this.debugLayer = markRaw(new Graphics());
                window.$pixi.stage.addChild(this.debugLayer as Graphics);
                this.spineIdleHighlighter = markRaw(new SpineIdleHighlighter(window.$pixi.renderer));
                window.$pixi.ticker.add(this.updateSpineHighlighter);
            } else {
                window.$pixi.ticker.remove(this.updateSpineHighlighter);
                window.$pixi.stage.removeChild(this.debugLayer as Graphics);
                this.spineIdleHighlighter?.stopHighlights(window.$pixi.stage, this.debugLayer as Graphics);
                this.debugLayer = null;
                this.spineIdleHighlighter = null;
                this.globalFrame = 0;
            }
        }
    }
});
